        return -round_half_to_even(-n)

    if n.is_integer():
       return int(n)

    fractional_part = n - int(n)
    if fractional_part >= 0.5:
        return int(n) + 1
    elif fractional_part > 0.25 and fractional_part < 0.5:
        return int(n)
    elif fractional_part > 0.25:
