def difference(d1, d2, level=-1):
    if level == -1:
        result = {}
        for key in d1:
            if key not in d2:
                result[key] = d1[key]
            else:
                if isinstance(d1[key], dict):
                    sub_result = difference(d1[key], d2[key], level=-1)
                    if sub_result:
                        result[key] = sub_result
        return result
    else:
        for key in d1:
            if key not in d2:
                yield key
        for key in d2:
            if key in d1 and isinstance(d1[key], dict) and level > 0:
                yield from difference(d1[key], d2[key], level=level-1)

def fill(self, coord, weight=1):
