        raise ValueError("Coordinate out of bounds")

    for r in range(self.size, 0, -1):
        if self.data[r - 1][coord[0]] > 0:
            for c in range(coord[1] + 1):
                if weight > 0:
                    self.data[r - c][coord[0]] += weight
            break

