def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
    ) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
        if not isinstance(sql, (str, bytes)):
            raise TypeError("Sql must be either str or bytes")
        if not params or not isinstance(params, (dict, list)):
            raise ValueError("Params must be either dict or list")

        formatted_sql = sql[:]  # Create a copy of the SQL to avoid modifying the original
        out_style_params = []

        if SQLParams.in_style == 'named':
            if not isinstance(params, Mapping):
                raise TypeError("If in_style is named parameters, params must be a Mapping")
            for param, value in params.items():
                formatted_sql = formatted_sql.replace(f":{param}", f"?")
                out_style_params.append((param, value))
        elif SQLParams.in_style == 'ordinal':
            if not isinstance(params, Sequence):
                raise TypeError("If in_style is ordinal parameters, params must be a Sequence")
            for idx, param_value in enumerate(params):
                formatted_sql = formatted_sql.replace("?", f"param_val_{idx}")
                out_style_params.append((idx, param_value))
        else:
            raise ValueError("Invalid in_style for SQL formatting")

        return formatted_sql, out_style_params

def formatmany(sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if not isinstance(sql, (str, bytes)):
        raise TypeError("Invalid input type. Expecting str or bytes.")

    if not isinstance(many_params, (Iterable, Sequence)):
        raise TypeError("Invalid input type. Expecting iterable or sequence.")

    out_params = []

    for params in many_params:
        if isinstance(params, Mapping):
            out_params.append({k: params[k] for k in SQLParams.in_style.get_keys()})
        elif isinstance(params, Sequence):
            out_params.append(params)
        else:
            raise TypeError("Invalid parameter type. Expecting mapping or sequence.")

    return sql, out_params

