        return str(self)
    pretty_str = '{'
    if debug:
        print("Indent:", indent)
    for i, element in enumerate(self.elements):
        if debug:
            print(f"Element at {i}: {element}")
        if isinstance(element, (dict, list)):
            pretty_str += indent * 2 + '  ' + pretty(element, indent + 2, debug) + ',\n'
