def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
            hook.

    """
    if not isinstance(hook, HookType):
        raise ValueError("hook must be an instance of HookType")

    def decorator(listener):
        if not callable(listener):
            raise ValueError("listener must be a callable function")

        if hook not in self.registry:
            self.registry[hook] = []

        self.registry[hook].append(listener)

        def wrapper(*args, **kwargs):
            for listener in self.registry[hook]:
                listener(*args, **kwargs)
        return wrapper

    return decorator

def _fromutc(self, dt: datetime) -> datetime:
    ambiguous_timedeltas = [ timedelta(days=1), timedelta(days=-1) ]
    ambiguous_timestamps = []

    for delta in ambiguous_timedeltas:
        ambiguous_timestamp = dt + delta
        if ambiguous_timestamp.replace(tzinfo=timezone.utc) == dt.replace(tzinfo=timezone.utc):
            ambiguous_timestamps.append(ambiguous_timestamp.timestamp())

    most_recent_ambiguous_timestamp = max(ambiguous_timestamps)
    ambiguous_datetime = datetime.fromtimestamp(most_recent_ambiguous_timestamp, tz=timezone.utc)

    if ambiguous_datetime == dt:
        dt = ambiguous_datetime
    else:
        raise Exception("Ambiguous timestamp occurred.")

    return dt

