                    merge_dict[k] = v
                else:
                    if not isinstance(merge_dict[k], MappingNode):
                        merge_dict[k] = v
                    else:
                        merge_dict[k] = deep_merge_nodes([(k, v)])
        elif not isinstance(key, str) or not isinstance(value, (str, int)):
            continue
        else:
            if key in merge_dict:
                if isinstance(merge_dict[key], MappingNode) or isinstance(value, MappingNode):
                    merge_dict[key] = deep_merge_nodes([(key, value)])
