    return [((None if key == ScalarNode(tag='tag:yaml.org,2002:str', value='') else key), merge_dict[key]) for key in sorted(merge_dict.keys())]

def parse_arguments(*unparsed_arguments):
    import argparse

    def add_subparser(parent_parser, name):
        subparser = parent_parser.add_parser(name, help='Subparser description')
        subparser.set_defaults(func=None)
        return subparser

    def add_global_parser(subparser):
        global_group = subparser.add_argument_group('Global options')
        global_group.add_argument('--global-arg', type=str, help='Global argument')

    def handle_subparser_args(args, subparser):
        if args.func:
            args.func(args)

    parser = argparse.ArgumentParser(description='Main script description')
    global_parser = add_global_parser(parser)
    subparsers = parser.add_subparsers()
    add_subparser(subparsers, 'subparser1')
    add_subparser(subparsers, 'subparser2')

    args = parser.parse_args(unparsed_arguments)
    handle_subparser_args(args, args.subparser)
    return {
        name: args[name] for name, arg in args._get_kwargs() if name.startswith('global_')
    }

def parse_subparser_arguments(unparsed_arguments, subparsers):
    runtime_errors = []

    parsed_arguments = {}
    remaining_arguments = []

    for subparser_name, subparser in subparsers.items():
        parsed_arguments[subparser_name] = None

        args, uneaten_args = subparser.parse_known_args(unparsed_arguments)
        if uneaten_args:
            remaining_arguments.extend(uneaten_args)

        # If there's a RuntimeError, likely due to conflicting arguments, add it to the list
        if isinstance(args, argparse.ArgumentTypeError) or [isinstance(arg, ImportError) for arg in uneaten_args]:
            runtime_errors.append((subparser, args))

    return parsed_arguments, remaining_arguments, runtime_errors

def deep_merge_nodes(nodes):
    merged_dict = {}

    for key, value in nodes:
        if key in merged_dict:
            if isinstance(value, MappingNode) and isinstance(merged_dict[key], MappingNode):
                deep_merge_nodes([(key, y) for y in value + merged_dict[key]])
            else:
                merged_dict[key] = value
        else:
            merged_dict[key] = value

    return list(merged_dict.items())

def parser_flags(parser):
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = " ".join(parser.prog.split())
    flags += " " + " ".join(parser.description.split())

    keyword_arg_values = parser.get_default_kwargs()
    for key, value in keyword_arg_values.items():
        argparse_value = parser.get_default_value(key)
        arg_str = f"--{key}"
        if value != argparse_value:
            arg_str += f"={value}"

        flags += " " + arg_str

    return flags

