def size_to_bytes(size: str) -> int:
    units = ["K", "M", "G", "T", "P", "E", "Z", "Y"]
    if not any(size.endswith(unit) for unit in units):
        raise ValueError("Invalid size format. Please use one of K, M, G, T, P, E, Z, or Y")

    # Convert size to bytes, being careful to handle cases where user input is rounded
    match = re.match(r'(\d+(\.\d+)?)([KMGTPEZY])', size)
    if match:
        number = float(match.group(1))
        multiplier = 1
        for letter in match.group(3):
            multiplier *= 10
        return int(number * multiplier)
    else:
        raise ValueError("Invalid size format")

