def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet or not isinstance(number, int) or number < 0:
        raise ValueError("Invalid input: integer must be non-negative, alphabet must be provided and not empty")

    result = ""
    if padding is not None and padding > 0:
        result = '0' * padding + result

    converted_number = ord(alphabet[0])
    while converted_number <= ord(alphabet[len(alphabet) - 1]):
        for i in range(10):
            digit = (number % 10) * pow(10, len(result))
            if digit <= converted_number:
                result += alphabet[converted_number - digit]
                number //= 10
                break
            converted_number += 1

    return result

