def split(s, platform=''):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not s:
        return []

    if platform == 'this':
        platform = 'posix' if 'win' not in sys.platform else 'cmd'
    elif platform not in ('posix', 'cmd'):
        raise ValueError("Invalid platform value. Expected 'posix' or 'cmd'.")

    # Use the appropriate regex to split the input string
    if platform == 'posix':
        return re.split(r' ?[;+\s]\s*', s)
    else:
        return re.split(r' ?[;+]?\s*', s)

def parse_frequency(frequency):
    try:
        if frequency is None or frequency.lower() == "always":
            return None
        if re.match(r'\d+(\s+)([a-zA-Z]+)', frequency):
            match = re.search(r'\d+(\s+)([a-zA-Z]+)', frequency)
            number = int(match.group(1))
            unit = match.group(2).lower()
            assert number > 0, "Frequency value must be greater than 0"
            if unit == 'second':
                return timedelta(seconds=number)
            elif unit == 'minute':
                return timedelta(minutes=number)
            elif unit == 'hour':
                return timedelta(hours=number)
            elif unit == 'day':
                return timedelta(days=number)
            elif unit == 'week':
                return timedelta(weeks=number)
            elif unit == 'month':
                return timedelta(days=number * 30)  # Assuming average month has 30 days
            else:
                raise ValueError(f"Unsupported unit: {unit}")
        else:
            raise ValueError(f"Invalid frequency format: {frequency}")
    except ValueError as e:
        print(f"Error parsing frequency: {e}")
        return None

