def find_roots(graph, prop, roots=None):
    if not issubclass(graph, rdflib.Graph) or not isinstance(prop, rdflib.URIRef):
        raise ValueError("graph must be a rdflib.Graph and prop must be a rdflib.URIRef")

    if roots is None:
        roots = set()

    # Collect all subjects (instances) of the property
    instances = set([s for s, p, o in graph if p == prop])

    # Process the set of instances recursively
    for instance in instances:
        if instance in roots:  # Skip if already processed
            continue
        roots.add(instance)
        # Recursively add children that are also instances
        for subject, predicate, object in graph:
            if subject == instance and predicate == prop:
                roots.add(object)

    return roots

