def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    if bufsize is not None:
        raise ValueError(f"bufsize incompatible with type {type(seq)}")
    if isinstance(seq, (list, tuple, set)):
        return seq, type(seq)
    elif isinstance(seq, str):
        return seq, 'str'
    elif isinstance(seq, int):
        return seq, 'int'
    elif isinstance(seq, float):
        return seq, 'float'
    elif isinstance(seq, bool):
        return seq, 'bool'
    else:
        raise TypeError(f"Unsupported type {type(seq)}")

def scale(self, other=None, recompute=False):
        if other is None:
            scale = self.histsum / self.nentries if self.nentries > 0 else 0
        else:
            if other == 0:
                raise ValueError("Cannot rescale histogram to 0.")
            scale = other
            self.histsum = scale * self.nentries
            self.nentries = self.histsum

        if recompute:  # Reset scale if recompute flag is used
            self.histsum = self.histsum / self.nentries
            self.nentries = self.histsum

        return scale

def _verify(iface, candidate, tentative=False, vtype=None):
    if tentative:
        return True  # Skip if tentative and verify

    implemented = iface.providedBy(candidate) or (hasattr(candidate, 'provides') and iface.provides(candidate))
    if not implemented:
        raise zope.interface.Invalid("Candidate must provide interface {} using iface.providedBy or candidate provides iface.".format(iface))

    candidate_methods = candidate.__dict__
    interface_methods = iface.implementedInterface(destination=True)

    missing_methods = set(interface_methods) - set(candidate_methods)
    multiple_methods = len(missing_methods) > 1

    if missing_methods:
        if multiple_methods:
            raise zope.interface.Invalid(f"Multiple methods needed: {', '.join(missing_methods)}.")
        else:
            raise zope.interface.Invalid(f"At least one method needed: {missing_methods}.")

    missing_attributes = set(interface_methods) - set(getattr(candidate, '__dict__', {}))
    if missing_attributes:
        if multiple_attributes:
            raise zope.interface.Invalid(f"Multiple attributes needed: {', '.join(missing_attributes)}.")
        else:
            raise zope.interface.Invalid(f"At least one attribute needed: {missing_attributes}.")

    return True

def verifyObject(iface, candidate, tentative=False):
    provided_info = iface.providedBy(candidate) if not tentative else None
    required_methods = iface.allMethods()
    required_attributes = iface.allAttributes()

    if provided_info is None:
        raise Invalid(f"The candidate does not provide the interface '{iface.name}'.")

    missing_methods = []
    missing_attributes = []

    for method_name in required_methods:
        if method_name not in candidate.__dict__:
            missing_methods.append(method_name)

    for attr_name in required_attributes:
        if not hasattr(candidate, attr_name):
            missing_attributes.append(attr_name)

    if missing_methods or missing_attributes:
        errors = missing_methods + missing_attributes
        if len(errors) == 1:
            raise Invalid(f"The candidate is missing the attribute or method: {errors[0]}.")
        else:
            raise Invalid(f"The candidate is missing the attributes or methods: {', '.join(errors)}.")

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        if not hasattr(candidate, iface):
            return False
        if tentative and not hasattr(candidate, 'test_hook'):
            return False
        return True
    except AttributeError as e:
        return False

def popitem(self):
    if not self._dict:
        raise KeyError('popitem(): dictionary is empty')

    least_frequent_key, value = min(self._dict.items(), key=lambda x: x[1])
    del self._dict[least_frequent_key]
    return least_frequent_key, value

