        response = requests.head(url)
        if response.status_code == 200:
            return response.headers.get('content-type')
        else:
            return None
    except requests.exceptions.RequestException as e:
        print(f"Error fetching content type: {e}")
        return None

def test_tag(tag: str) -> bool:
    # Ensure the tag is not empty
    if not tag:
        raise ValueError("Tag cannot be empty")

    # Check if the tag consists only of alphanumeric characters and underscores
    if not tag.isalnum() and not tag.startswith('_'):
        raise ValueError("Tag must consist only of alphanumeric characters and underscores or start with an underscore")

    # Check if the tag is not a reserved word
    if tag.lower() in ['and', 'or', 'not']:
        raise ValueError("Tag is a reserved word")

    return True

def xml_children_as_dict(node):
    '''
    Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    '''
    if not isinstance(node, dict) or 'children' not in node:
        raise ValueError("Invalid input: Node must be a dictionary with a list of child nodes.")

    res = {}
    for child in node['children']:
        if not isinstance(child, dict) or 'tag_name' not in child:
            raise ValueError(f"Invalid child node format: Child must be a dictionary with a 'tag_name' key.")
        res[child['tag_name']] = child
    return res

