def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    import xml.etree.ElementTree as ET
    from typing import Dict

    def _is_json(data: str) -> bool:
        try:
            json.loads(data)
            return True
        except ValueError:
            return False

    if _is_json(document):
        return json.loads(document)
    else:
        root = ET.fromstring(document)
        if root.tag != '{http://www.w3.org/ns/xsl-discovery}webfinger':
            raise ValueError("Invalid XRD format")

        result = {}
        for name, value in root.attrib.items():
            result[name] = value

        for relation in root.findall('{http://www.w3.org/ns/xsl-discovery}relation'):
            rel, type = relation.text.split(' ', 1)
            if rel == 'https://diaspora.github.io/diaspora_federation/discovery/webfinger#actor':
                result['actor'] = type.split('://')[-1]
            elif rel == 'https://diaspora.github.io/diaspora_federation/discovery/webfinger#site':
                result['site'] = type.split('://')[-1]

        return result

