def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        # Send a GET request to the Diaspora host-meta endpoint
        response = requests.get(f"https://{host}/host-meta.json")

        # Check if the request was successful
        if response.status_code == 200:
            # Parse the JSON response
            return json.loads(response.text)
        else:
            # Return None if the request failed
            return None
    except requests.exceptions.RequestException as e:
        # Handle exceptions such as invalid host, rate limiting, etc.
        print(f"Error retrieving Diaspora host-meta from {host}: {e}")
        return None

def dict_insert(dic, val, key, *keys):
    current_dict = dic
    for key_str in (key,) + keys:
        if key_str not in current_dict:
            current_dict[key_str] = {}
        current_dict = current_dict[key_str]
    current_dict[key] = val

def list_of_file_names(settings_dirs, spec_option):
    if spec_option not in ['all', 'selected']:
        raise ValueError("Invalid option for spec_option. Must be 'all' or 'selected'.")

    file_paths = []
    for setting_dir in settings_dirs:
        files = os.listdir(setting_dir)
        for file in files:
            file_path = os.path.join(setting_dir, file)
            if os.path.isfile(file_path) and file.endswith(".ini"):
                file_paths.append(file_path)

    if spec_option == 'all':
        return file_paths
    else:
        return [file_path for file_path in file_paths if os.path.splitext(file_path)[0] in spec_option]

