def _include_groups(self, parser_dict):
    if not isinstance(parser_dict, dict):
        raise ValueError("Input is not a dictionary")
    include_path = parser_dict.get('include_path', None)
    if include_path is None:
        raise ValueError("Include path not specified")
    if not include_path[0] in '\\/:':
        raise ValueError("Include path should start with a forward or backward slash")
    if not os.path.exists(include_path):
        raise FileExistsError(f"Include path {include_path} does not exist")
    group_file = include_path + '/groups.json'
    if not os.path.exists(group_file):
        raise FileExistsError(f"Group file {group_file} does not exist")
    return json.load(open(group_file))

