def validate_min_max_args(self, args):
    def get_min_max_value(value):
        return min(value), max(value)

    if not args:
        raise ValueError("The function requires at least one argument.")
    try:
        min_value, max_value = get_min_max_value(args[0])
        for arg in args[1:]:
            if arg < min_value or arg > max_value:
                raise ValueError(f"Argument {arg} is out of the specified range [{min_value}, {max_value}]")
    except TypeError:
        raise TypeError("All provided arguments must be of a numeric type.")

