            # Ensure the type_name is not None
            if type_name is None:
                raise ValueError("Type name cannot be None")

            # Ensure the option_name is not None
            if option_name is None:
                raise ValueError("Option name cannot be None")

            # Ensure the spec_option is not None
            if spec_option is None:
                raise ValueError("Spec option cannot be None")

            # Initialize the complex type
            complex_type = None

            # Build the complex type based on the subcommand and type name
            if subcommand.startswith('create'):
                if type_name == 'task':
                    complex_type = create_task_type(option_name, spec_option)
                elif type_name == 'file':
                    complex_type = create_file_type(option_name, spec_option)
                elif type_name == 'user':
                    complex_type = create_user_type(option_name, spec_option)
                else:
