def get_nested_custom_and_control_args(self, args: List[str]) -> Tuple[Dict[str, str], Dict[str, str]]:
    control_args = {}
    nested_args = {}

    # Validate input
    if not isinstance(args, list):
        raise ValueError("args must be a list of strings")

    for arg in args:
        # Separate control and nested arguments
        if ":c:" in arg:
            control_args = {k: v for k, v in arg.split("::", 1)}
        elif ":n:" in arg:
            nested_args = {k: v for k, v in arg.split(":n:", 1)}
        else:
            raise ValueError(f"Invalid argument format: {arg}")

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if vars_dict is None:
        raise ValueError("vars_dict cannot be None")
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is not None:
        if not isinstance(extra_vars, list):
            raise TypeError("extra_vars must be a list")
        if len(extra_vars) == 0:
            return vars_dict
    vars_dict.update(extra_vars or [])
    return vars_dict

def __run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    # Check if required variables are provided
    if vars_dict is None:
        raise ValueError("vars_dict must not be None")
    if cli_args is None:
        raise ValueError("cli_args must not be None")
    if ir_workspace is None:
        raise ValueError("ir_workspace must not be None")
    if ir_plugin is None:
        raise ValueError("ir_plugin must not be None")

    # Formulate Ansible command with variables and arguments
    ansible_cmd = ["ansible-playbook"] + cli_args
    for k, v in vars_dict.items():
        ansible_cmd.append(f"-e '{k}={v}'")

    try:
        # Execute ansible command
        ansible_results = subprocess.run(ansible_cmd, capture_output=True, text=True, check=True)
        return ansible_results.stdout

    except subprocess.CalledProcessError as e:
        # Handle Ansible command execution errors
        raise RuntimeError(f"Failed to execute Ansible playbook: {e.stderr}")

