def get_plugin_spec_flatten_dict(plugin_dir):
    flatten_dict = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith(".json"):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    spec = json.load(f)
                    for key, value in spec.items():
                        if isinstance(value, dict):
                            flatten_dict.update(_merge_dicts(flatten_dict, value, key))
                        else:
                            flatten_dict[key] = value
    return flatten_dict

def inject_config(self):
        """Set the environment variable for config path, if it is undefined."""
        if os.name == 'posix':
            self.config_path = '/etc/config.zip'  # Setup on Unix-like systems
        elif os.name == 'nt':
            self.config_path = 'C:\\Users\\YourName\\Documents\\config.zip'  # Setup on Windows
        else:
            raise ValueError("Unsupported operating system.")
        os.environ['CONFIG_PATH'] = self.config_path

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
